package main

import (
	"bytes"
	"embed"
	"fmt"
	"regexp"
	"strings"
	"text/template"
	"unicode"
)

//go:embed templates/*.tmpl
var templates embed.FS

// header marks the generated files. It is split so that this source file
// itself does not look generated to tools.
const header = "Code generated by go run ./internal/cmd/apidoc; " + "DO NOT EDIT."

// render executes the template name with a.
func render(a *API, name string) ([]byte, error) {
	funcs := template.FuncMap{
		"anchor":      anchor,
		"heading":     heading,
		"signature":   signature,
		"doc":         readmeLinks,
		"cell":        cell,
		"description": func(f Field) string { return strings.TrimSpace(f.Doc + " " + f.Note) },
		"typeCell":    func(typ string) string { return typeCell(a, typ) },
		"jsdoc":       jsdoc,
		"tsdoc":       tsdoc,
	}
	t, err := template.New(name).Funcs(funcs).ParseFS(templates, "templates/"+name)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	data := struct {
		*API
		Header string
	}{a, header}
	if err := t.Execute(&b, data); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}

// heading returns the Markdown heading of a method.
func heading(m Method) string {
	names := make([]string, len(m.Params))
	for i, p := range m.Params {
		names[i] = p.Name
		if p.Optional {
			names[i] += "?"
		}
	}
	return fmt.Sprintf("`client.%s(%s)`", m.Name, strings.Join(names, ", "))
}

// signature returns the TypeScript signature of a method.
func signature(m Method) string {
	params := make([]string, len(m.Params))
	for i, p := range m.Params {
		opt := ""
		if p.Optional {
			opt = "?"
		}
		params[i] = fmt.Sprintf("%s%s: %s", p.Name, opt, p.Type)
	}
	return fmt.Sprintf("%s(%s): %s", m.Name, strings.Join(params, ", "), m.Returns)
}

// typeCell formats a type for a Markdown table cell, linking the types
// defined in the reference.
func typeCell(a *API, typ string) string {
	for _, t := range a.Types {
		if t.Name == typ {
			return fmt.Sprintf("[`%s`](#%s)", typ, anchor(typ))
		}
	}
	return "`" + strings.ReplaceAll(typ, "|", `\|`) + "`"
}

// tsdoc returns the JSDoc text of a field.
func tsdoc(f Field) string {
	doc := strings.TrimSpace(f.Doc + "\n\n" + f.Note)
	if f.Default != "" {
		doc += "\n\nDefault: " + f.Default
	}
	return doc
}

// jsdoc formats doc as a JSDoc comment indented by indent, without the
// trailing newline.
func jsdoc(indent, doc string) string {
	lines := []string{indent + "/**"}
	for line := range strings.SplitSeq(strings.ReplaceAll(doc, "*/", `*\/`), "\n") {
		lines = append(lines, strings.TrimRight(indent+" * "+line, " "))
	}
	lines = append(lines, indent+" */")
	return strings.Join(lines, "\n")
}

// readmeSection matches a reference to a README section in doc comments.
var readmeSection = regexp.MustCompile(`the\s+([A-Za-z][A-Za-z\s]*?)\s+section\s+of\s+README`)

// readmeLinks links the references to README sections.
func readmeLinks(doc string) string {
	return readmeSection.ReplaceAllStringFunc(doc, func(m string) string {
		name := strings.Join(strings.Fields(readmeSection.FindStringSubmatch(m)[1]), " ")
		return fmt.Sprintf("[%s](../README.md#%s) in README", name, anchor(name))
	})
}

// cell formats text for a Markdown table cell.
func cell(s string) string {
	return strings.ReplaceAll(strings.Join(strings.Fields(s), " "), "|", `\|`)
}

// anchor returns the GitHub anchor of a heading.
func anchor(heading string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(heading) {
		switch {
		case unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-' || r == '_':
			b.WriteRune(r)
		case r == ' ':
			b.WriteRune('-')
		}
	}
	return b.String()
}
